use rpncalc::evaluate;

#[test]
fn test_simple_add() {
    assert_eq!(evaluate("3 4 +").unwrap(), 7.0);
}

#[test]
fn test_subtract() {
    assert_eq!(evaluate("10 3 -").unwrap(), 7.0);
}

#[test]
fn test_multiply() {
    assert_eq!(evaluate("6 7 *").unwrap(), 42.0);
}

#[test]
fn test_divide() {
    assert!((evaluate("10 4 /").unwrap() - 2.5).abs() < 1e-9);
}

#[test]
fn test_complex_expression() {
    // (3 + 4) * 2 = 14 in RPN: 3 4 + 2 *
    assert_eq!(evaluate("3 4 + 2 *").unwrap(), 14.0);
}

#[test]
fn test_empty_expression_error() {
    assert!(evaluate("").is_err());
}

#[test]
fn test_too_many_operands_error() {
    assert!(evaluate("1 2 3").is_err());
}

